{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://dongke.app/schema/workout-plan-v1.json","title":"DongKeWorkoutPlan","description":"动刻周训练计划的唯一数据契约。AI 直连输出、粘贴解析、备份导出、SwiftData 持久化四条链路共用这一份结构。硬约束：所有字段必填；无内容的字符串填空串，无内容的数组填 []，无数值的数值填 0；不得出现 null；不得新增未定义字段；days 固定 7 项。取值范围（组数、休息秒数、时间格式等）由 App 内 PlanValidator 校验，本 Schema 只表达结构与枚举。","type":"object","additionalProperties":false,"required":["schemaVersion","meta","days","cautions"],"properties":{"schemaVersion":{"type":"integer","enum":[1],"description":"结构版本号，当前固定为 1。不兼容变更时升为 2，解析器按版本分派。"},"meta":{"$ref":"#/$defs/PlanMeta"},"days":{"type":"array","description":"周一到周日共 7 项，顺序按 dayIndex 从 1 到 7，休息日也要占位（isRestDay 为 true）。","items":{"$ref":"#/$defs/PlanDay"}},"cautions":{"type":"array","description":"通用注意事项，例如关节疼痛须停训、动作幅度以无痛为限。无内容填 []。","items":{"type":"string"}}},"$defs":{"PlanMeta":{"type":"object","additionalProperties":false,"description":"计划级元信息，用于列表展示与再次生成时的上下文。","required":["title","goal","level","daysPerWeek","sessionMinutes","notes"],"properties":{"title":{"type":"string","description":"计划名称，不超过 24 个字，例如 居家减脂四周入门。"},"goal":{"type":"string","enum":["lose_fat","build_muscle","endurance","general_fitness","mobility"],"description":"训练目标。减脂选 lose_fat。"},"level":{"type":"string","enum":["beginner","intermediate","advanced"],"description":"训练水平，新手选 beginner。"},"daysPerWeek":{"type":"integer","description":"每周训练天数，取值 1 到 7。必须与 days 中 isRestDay 为 false 的天数一致。"},"sessionMinutes":{"type":"integer","description":"单次训练目标时长（分钟），含热身与放松，取值 5 到 120。"},"notes":{"type":"string","description":"计划总说明。无内容填空串。"}}},"PlanDay":{"type":"object","additionalProperties":false,"description":"一天的计划。休息日也必须有完整对象。","required":["dayIndex","weekday","isRestDay","title","scheduledTime","estimatedMinutes","blocks","notes"],"properties":{"dayIndex":{"type":"integer","description":"周内序号，1 表示周一，7 表示周日。"},"weekday":{"type":"string","enum":["monday","tuesday","wednesday","thursday","friday","saturday","sunday"],"description":"星期名，必须与 dayIndex 对应：1 对应 monday，7 对应 sunday。"},"isRestDay":{"type":"boolean","description":"true 表示休息日，此时 blocks 填 []，estimatedMinutes 填 0。"},"title":{"type":"string","description":"当天主题，例如 下肢力量、全身循环、主动恢复。休息日填 休息。"},"scheduledTime":{"type":"string","description":"建议开始时间，24 小时制 HH:mm，例如 19:30。用户未指定时填空串，表示不限时。"},"estimatedMinutes":{"type":"integer","description":"当天预计时长（分钟）。休息日填 0。"},"blocks":{"type":"array","description":"训练区块，按执行顺序排列。休息日填 []。","items":{"$ref":"#/$defs/ExerciseBlock"}},"notes":{"type":"string","description":"当天备注。无内容填空串。"}}},"ExerciseBlock":{"type":"object","additionalProperties":false,"description":"区块。warmup 热身、main 常规训练、circuit 循环、superset 超级组、cooldown 放松。循环与超级组用 rounds 表达轮数，items 里放该轮的若干个动作。","required":["blockId","kind","title","rounds","restBetweenItemsSec","restBetweenRoundsSec","items","notes"],"properties":{"blockId":{"type":"string","description":"块内唯一标识，建议 b1、b2 这类短串。"},"kind":{"type":"string","enum":["warmup","main","circuit","superset","cooldown"],"description":"区块类型。超级组选 superset，循环训练选 circuit，其余常规动作选 main。"},"title":{"type":"string","description":"区块名称，例如 动态热身、主训练、核心三连。"},"rounds":{"type":"integer","description":"循环轮数。非循环区块填 1。"},"restBetweenItemsSec":{"type":"integer","description":"同一轮内动作之间的休息秒数。超级组通常填 0。"},"restBetweenRoundsSec":{"type":"integer","description":"轮与轮之间的休息秒数。非循环区块填 0。"},"items":{"type":"array","description":"区块内动作，按执行顺序排列。","items":{"$ref":"#/$defs/ExercisePrescription"}},"notes":{"type":"string","description":"区块备注，例如 心率控制在最大心率 70%。无内容填空串。"}}},"ExercisePrescription":{"type":"object","additionalProperties":false,"description":"单个动作处方。表达做几组、每组做到什么程度、组间休息多久。","required":["itemId","catalogId","name","sets","target","restSec","tempo","load","notes"],"properties":{"itemId":{"type":"string","description":"项内唯一标识，建议 i1、i2 这类短串。"},"catalogId":{"type":"string","description":"动作库标识，取 App 内置动作库的 id，可用清单见系统提示第 4 条，不要臆造。库中没有的动作填 custom_ 前缀的自定义串，例如 custom_burpee。"},"name":{"type":"string","description":"动作中文名，例如 深蹲、跪姿俯卧撑、平板支撑。"},"sets":{"type":"integer","description":"组数，取值 1 到 20。"},"target":{"$ref":"#/$defs/SetTarget"},"restSec":{"type":"integer","description":"本动作组与组之间的休息秒数，取值 0 到 600。"},"tempo":{"type":"string","description":"节奏，格式为 下放秒数-底部停顿-上举秒数-顶部停顿，例如 3-1-1-0。不指定填空串。"},"load":{"$ref":"#/$defs/Load"},"notes":{"type":"string","description":"动作要点与常见错误提示，一到两句，不超过 60 字。无内容填空串。"}}},"SetTarget":{"type":"object","additionalProperties":false,"description":"单组的完成目标，三选一：次数、时长、距离。","required":["type","value","perSide"],"properties":{"type":{"type":"string","enum":["reps","duration_sec","distance_m"],"description":"目标类型。计次动作选 reps，平板支撑这类静力动作选 duration_sec，负重行走选 distance_m。"},"value":{"type":"integer","description":"目标数值。type 为 reps 时是次数，duration_sec 时是秒数，distance_m 时是米数。取值 1 到 3600。"},"perSide":{"type":"boolean","description":"true 表示每侧分别完成，例如 弓步每侧 12 次。"}}},"Load":{"type":"object","additionalProperties":false,"description":"负重描述。自重训练填 type 为 bodyweight、value 为 0。","required":["type","value"],"properties":{"type":{"type":"string","enum":["bodyweight","dumbbell","barbell","kettlebell","band","machine","other"],"description":"负重类型。居家场景常用 bodyweight、dumbbell、band。"},"value":{"type":"number","description":"单只重量（公斤），0 表示不指定或自重。可为整数。"}}}}}
"""#
